public int search(int[] nums, int target) {
    // Find the pivot index
    int pivot = findPivot(nums);

    // Check if the target is in the left or right half
    if (target < nums[pivot]) {
        return search(nums, 0, pivot - 1, target);
    } else if (target > nums[pivot]) {
        return search(nums, pivot + 1, nums.length - 1, target);
    } else {
        return pivot;
    }
}

private int search(int[] nums, int low, int high, int target) {
    while (low <= high) {
        int mid = (low + high) / 2;
        if (nums[mid] == target) {
            return mid;
        } else if (nums[mid] < target) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    return -1;
}

private int findPivot(int[] nums) {
    int low = 0;
    int high = nums.length - 1;

    while (low <= high) {
        int mid = (low + high) / 2;
        if (nums[mid] > nums[high]) {
            low = mid + 1;
        } else if (nums[mid] < nums[high]) {
            high = mid - 1;
        } else {
            return mid;
        }
    }

    return -1;
}

public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the number of elements to remove from the smallest and largest 5%
    int numElementsToRemove = (int) (arr.length * 0.05);

    // Remove the smallest and largest 5% of elements
    int[] trimmedArr = Arrays.copyOfRange(arr, numElementsToRemove, arr.length - numElementsToRemove);

    // Calculate the mean of the remaining elements
    double mean = trimmedArr.stream().mapToDouble(i -> i).average().getAsDouble();

    // Return the mean with an error within 10^-5
    return Math.round(mean * 100000) / 100000;
}

