public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with n nodes and edges
    Graph graph = new Graph(n, edges);

    // Initialize a queue to store the nodes to visit
    Queue<Integer> queue = new LinkedList<>();

    // Initialize a set to store the visited nodes
    Set<Integer> visited = new HashSet<>();

    // Initialize a variable to store the minimum time
    int minTime = 0;

    // Start from node 0
    queue.offer(0);
    visited.add(0);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node
        int current = queue.poll();

        // If the current node has an apple, add the time to collect it
        if (hasApple[current]) {
            minTime++;
        }

        // Loop through the neighbors of the current node
        for (int neighbor : graph.getNeighbors(current)) {
            // If the neighbor has not been visited, mark it as visited and add it to the queue
            if (!visited.contains(neighbor)) {
                queue.offer(neighbor);
                visited.add(neighbor);
            }
        }
    }

    // Return the minimum time
    return minTime;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    int[] charCount = new int[26];

    for (char c : s.toCharArray()) {
        charCount[c - 'a']++;
    }

    while (result.length() < s.length()) {
        int min = -1;
        int max = -1;

        for (int i = 0; i < 26; i++) {
            if (charCount[i] > 0 && (min == -1 || min > i)) {
                min = i;
            }
            if (charCount[i] > 0 && (max == -1 || max < i)) {
                max = i;
            }
        }

        if (min != -1) {
            result.append((char) (min + 'a'));
            charCount[min]--;
        }

        if (max != -1) {
            result.append((char) (max + 'a'));
            charCount[max]--;
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the sum of the array elements
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // Calculate the average of the array elements
    int average = sum / nums.length;

    // Check if the average is an integer
    if (average % 1 != 0) {
        return false;
    }

    // Check if the array can be split into two parts with the same average
    int leftSum = 0;
    for (int i = 0; i < nums.length / 2; i++) {
        leftSum += nums[i];
    }
    int rightSum = sum - leftSum;
    return leftSum == rightSum;
}

