private static int[][] permutations(int[] A) {
    int[][] permutations = new int[factorial(A.length)][A.length];
    for (int i = 0; i < permutations.length; i++) {
        int[] permutation = new int[A.length];
        for (int j = 0; j < A.length; j++) {
            permutation[j] = A[i % A.length];
            i /= A.length;
        }
        permutations[i] = permutation;
    }
    return permutations;
}

