        for (int j = 0; j < n; j++) {
            if (j == i) {
                num += "1";
            } else {
                num += "0";
            }
        }
        result.add(num);
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    // Check if the points are valid
    if (points.length != 3) {
        throw new IllegalArgumentException("Invalid number of points");
    }

    // Check if the points are collinear
    if (points[0][0] == points[1][0] && points[0][1] == points[1][1] && points[1][0] == points[2][0] && points[1][1] == points[2][1]) {
        return false;
    }

    // Calculate the determinant of the matrix formed by the points
    int determinant = (points[0][0] - points[1][0]) * (points[1][1] - points[2][1]) - (points[0][1] - points[1][1]) * (points[1][0] - points[2][0]);

    // Return true if the determinant is non-zero, which means the points form a boomerang
    return determinant != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int i2 = 0, i3 = 0, i5 = 0;
    for (int i = 1; i < n; i++) {
        int nextUglyNumber = Math.min(uglyNumbers[i2] * 2, Math.min(uglyNumbers[i3] * 3, uglyNumbers[i5] * 5));
        uglyNumbers[i] = nextUglyNumber;
        if (nextUglyNumber == uglyNumbers[i2] * 2) {
            i2++;
        }
        if (nextUglyNumber == uglyNumbers[i3] * 3) {
            i3++;
        }
        if (nextUglyNumber == uglyNumbers[i5] * 5) {
            i5++;
        }
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    int energy = 0;
    int maxEnergy = 0;
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            energy++;
        } else {
            maxEnergy = Math.max(energy, maxEnergy);
            energy = 1;
        }
    }
    return Math.max(energy, maxEnergy);
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    result.sort((a, b) -> a.compareTo(b));
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    // Initialize a hash set to store unique elements
    Set<Integer> uniqueElements = new HashSet<>();

    // Iterate over the input array and add unique elements to the hash set
    for (int num : nums) {
        if (!uniqueElements.contains(num)) {
            uniqueElements.add(num);
        }
    }

    // Initialize the sum variable
    int sum = 0;

    // Iterate over the hash set and add elements to the sum
    for (int element : uniqueElements) {
        sum += element;
    }

    return sum;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    for (int i = 1; i <= n; i++) {
        int root = (int)Math.sqrt(i);
        if (root * root == i) {
            count++;
        }
    }
    return count;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        char[] chars = word.toCharArray();
        Arrays.reverse(chars);
        result.append(new String(chars));
        if (i < words.length - 1) {
            result.append(" ");
        }
    }
    return result.toString();
}
